import type { ImgHTMLAttributes } from "react";
import { cn } from "@/lib/utils";

export interface EditorialImageProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, "src"> {
  src: string;
  alt: string;
  width: number;
  height: number;
}

/**
 * Responsive editorial image with AVIF/WebP sources generated by the local
 * image optimization script. Explicit dimensions reserve space and prevent
 * layout shift in the static export.
 */
export function EditorialImage({
  src,
  alt,
  width,
  height,
  loading = "lazy",
  className,
  ...props
}: EditorialImageProps) {
  const base = src.replace(/\.(jpg|jpeg|png)$/i, "");

  return (
    <picture className="block">
      <source srcSet={`${base}.avif`} type="image/avif" />
      <source srcSet={`${base}.webp`} type="image/webp" />
      <img
        src={src}
        alt={alt}
        width={width}
        height={height}
        loading={loading}
        decoding="async"
        className={cn("block h-auto w-full object-cover", className)}
        {...props}
      />
    </picture>
  );
}
